list_guild_members.afterResponse:
let page = response, members = [];
while (true) {
  members = members.concat(page);
  if (page.length !== 1000) break;
  page = call({method: 'GET', url: '/guilds/' + encodeURIComponent(inputs.guild_id) + '/members', query: {limit: '1000', after: page[page.length - 1].user.id}});
}
const search = inputs.shortText.trim().toLowerCase();
const matching = search ? members.filter(m => [m.user.username, m.user.global_name, m.nick].some(v => typeof v === 'string' && v.toLowerCase().includes(search))) : members;
if (matching.length === 0) return {disabled: true, options: [], placeholder: 'No members found'};
return {options: matching.map(m => ({value: m.user.id, label: m.user.username}))};

createGuildRole.beforeRequest:
const color = inputs.role_color.trim();
if (color) {
  const hex = color.startsWith('#') ? color.slice(1) : color;
  if (/^\d+$/.test(color)) {
    if (Number(color) > 16777215) throw new Error('Color must be between 0 and 16777215, received "' + color + '".');
    request.body.color = Number(color);
  } else if (/^[0-9a-fA-F]{6}$/.test(hex)) request.body.color = parseInt(hex, 16);
  else throw new Error('Color must be a hex value like #5865F2 or a decimal RGB number, received "' + color + '".');
}
if (!inputs.creation_reason) { delete request.headers['X-Audit-Log-Reason']; }
return request;

discord_find_member.beforeRequest:
const form = v => encodeURIComponent(v).replace(/[!'()~]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
request.url += '?query=' + form(inputs.query) + '&limit=' + form(String(inputs.limit === '' ? 10 : Number(inputs.limit)));
return request;

discord_list_messages.beforeRequest:
if ([inputs.before, inputs.after, inputs.around].filter(c => c).length > 1) throw new Error('before, after, and around are mutually exclusive — supply at most one.');
let limit = inputs.limit === '' ? 50 : Number(inputs.limit);
if (limit < 1) limit = 1;
if (limit > 100) limit = 100;
request.query.limit = String(limit);
return request;

discord_bulk_delete_messages.beforeRequest:
const ids = request.body.messages || [];
if (ids.length < 2 || ids.length > 100) throw new Error('Bulk delete requires between 2 and 100 message IDs.');
return request;

discord_add_reaction.beforeRequest:
const custom = /^(.+):(\d+)$/.exec(inputs.emoji);
const emoji = custom ? encodeURIComponent(custom[1]) + ':' + custom[2] : encodeURIComponent(inputs.emoji);
request.url = '/channels/' + encodeURIComponent(inputs.channel_id) + '/messages/' + encodeURIComponent(inputs.message_id) + '/reactions/' + emoji + '/@me';
return request;

