discord_create_thread.beforeRequest:
if (inputs.type !== '') request.body.type = Number(inputs.type);
if (inputs.auto_archive_duration !== '') request.body.auto_archive_duration = Number(inputs.auto_archive_duration);
if (inputs.message) request.body.message = {content: inputs.message};
return request;

