discord_update_role.beforeRequest:
const tri = v => { const t = v.trim().toLowerCase(); if (t === 'yes' || t === 'true') return true; if (t === 'no' || t === 'false') return false; return undefined; };
const hoist = tri(inputs.hoist), mentionable = tri(inputs.mentionable);
if (hoist !== undefined) request.body.hoist = hoist;
if (mentionable !== undefined) request.body.mentionable = mentionable;
return request;

discord_create_scheduled_event.beforeRequest:
const type = Number(inputs.entity_type);
if (type === 3) {
  if (!inputs.location || !inputs.scheduled_end_time) throw new Error('An EXTERNAL event requires both a Location and a Scheduled End Time.');
} else if (!inputs.channel_id) throw new Error('A STAGE_INSTANCE or VOICE event requires a Channel ID.');
const body = {name: inputs.name, scheduled_start_time: inputs.scheduled_start_time, entity_type: type, privacy_level: 2};
if (inputs.description) body.description = inputs.description;
if (type === 3) {
  body.entity_metadata = {location: inputs.location};
  body.scheduled_end_time = inputs.scheduled_end_time;
} else body.channel_id = inputs.channel_id;
request.body = body;
return request;

discord_update_scheduled_event.beforeRequest:
if (!request.body) request.body = {};
if (inputs.status !== '') request.body.status = Number(inputs.status);
return request;
